  setup(){if(this.ctx)return true;const AC=globalThis.AudioContext||globalThis.webkitAudioContext;if(!AC)return false;try{const c=this.ctx=new AC();this.master=c.createGain();this.fx=c.createGain();this.music=c.createGain();this.musicDuck=c.createGain();this.compressor=c.createDynamicsCompressor();this.compressor.threshold.value=-17;this.compressor.knee.value=15;this.compressor.ratio.value=5;this.compressor.attack.value=.005;this.compressor.release.value=.22;const limiter=c.createDynamicsCompressor();limiter.threshold.value=-2;limiter.knee.value=0;limiter.ratio.value=20;limiter.attack.value=.001;limiter.release.value=.09;this.fx.connect(this.master);this.music.connect(this.musicDuck).connect(this.master);this.master.connect(this.compressor).connect(limiter).connect(c.destination);this.reverb=c.createConvolver();const length=Math.floor(c.sampleRate*1.8),buffer=c.createBuffer(2,length,c.sampleRate);for(let ch=0;ch<2;ch++){const a=buffer.getChannelData(ch);for(let i=0;i<length;i++)a[i]=(Math.random()*2-1)*(1-i/length)**3.6*.6;}this.reverb.buffer=buffer;const wet=c.createGain();wet.gain.value=.22;this.reverb.connect(wet).connect(this.master);this.noise=c.createBuffer(1,c.sampleRate,c.sampleRate);const data=this.noise.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;this.apply();this.nextBeat=c.currentTime+.08;this.scheduler=setInterval(()=>this.schedule(),100);return true;}catch{return false;}}
  async unlock(){if(!this.settings.enabled)return;if(!this.setup())return;try{if(this.ctx.state==='suspended')await this.ctx.resume();}catch{}}
